#!/usr/bin/env bash
# Rebuilds app/src/main/res/raw/licences.txt from docs/security/licences.md (itself generated by scripts/licences.sh).
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
out="$root/app/src/main/res/raw/licences.txt"
{
  echo "RiskMandate"
  echo
  echo "Licensed under the Apache License, Version 2.0."
  echo "Copyright (c) TODO: copyright holder (Dinis to confirm)"
  echo "You may obtain a copy of the licence at https://www.apache.org/licenses/LICENSE-2.0"
  echo "Unless required by applicable law or agreed to in writing, the software is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND."
  echo
  echo "Third-party libraries (all Apache License, Version 2.0):"
  echo
  awk -F'|' '/^\| [a-z]/ && $2 !~ /Artifact/ { gsub(/^ +| +$/, "", $2); gsub(/^ +| +$/, "", $3); print "- " $2 " (" $3 ")" }' "$root/docs/security/licences.md"
} > "$out"
